/** Unqualified method name. */
export type MethodName = keyof Methods;
/** Request params of method `M`. */
export type RequestOf<M extends MethodName> = Methods[M]["request"];
/** Response of method `M`. */
export type ResponseOf<M extends MethodName> = Methods[M]["response"];
/** Names of command methods. */
export type CommandName = { [K in MethodName]: Methods[K]["kind"] extends "command" ? K : never }[MethodName];
/** Names of query methods. */
export type QueryName = { [K in MethodName]: Methods[K]["kind"] extends "query" ? K : never }[MethodName];

